#!/usr/bin/env bash
# Static checks of the container images, without a Docker daemon:
#   - the Dockerfile of each image exists: server's is generated by Gradle into
#     server/build/docker/main (run `./gradlew :server:buildLayers :server:dockerfile` first),
#     jobs/Dockerfile and web/Dockerfile are checked in,
#   - every FROM names an explicit tag that is not `latest` (no bare or moving reference),
#   - the final stage of every Dockerfile sets a non-root USER,
#   - the web build context (the repository root) ignores local build output and dependencies.
# server and jobs are built from the Gradle-prepared contexts, see README "Container images".
set -euo pipefail

cd "$(dirname "$0")/.."

fail=0
report() {
  echo "FAIL: $*" >&2
  fail=1
}

components=(server jobs web)

for component in "${components[@]}"; do
  case "$component" in
    server) dockerfile="server/build/docker/main/Dockerfile" ;;
    *) dockerfile="$component/Dockerfile" ;;
  esac
  if [[ ! -f "$dockerfile" ]]; then
    report "$dockerfile does not exist (for server, run ./gradlew :server:buildLayers :server:dockerfile)"
    continue
  fi

  # Stage names declared so far; a FROM that names one of them is a stage reference, not an image.
  stages=" "
  while read -r _ ref rest; do
    alias=""
    if [[ "$rest" =~ ^[Aa][Ss][[:space:]]+([^[:space:]]+) ]]; then
      alias="${BASH_REMATCH[1]}"
    fi
    if [[ "$stages" != *" $ref "* ]]; then
      if [[ "$ref" == *:latest || "$ref" == latest ]]; then
        report "$dockerfile uses the latest tag: $ref"
      elif [[ "$ref" == *@* ]]; then
        : # pinned by digest, which is exact
      elif [[ "${ref##*/}" != *:* ]]; then
        report "$dockerfile has no explicit tag: $ref"
      fi
    fi
    if [[ -n "$alias" ]]; then
      stages="$stages$alias "
    fi
  done < <(grep -E '^[[:space:]]*FROM[[:space:]]' "$dockerfile" | tr -s ' \t' ' ')

  # USER of the final stage: the last USER line after the last FROM.
  final_user="$(awk '/^[[:space:]]*FROM[[:space:]]/ {user=""} /^[[:space:]]*USER[[:space:]]/ {user=$2} END {print user}' "$dockerfile")"
  if [[ -z "$final_user" ]]; then
    report "$dockerfile does not set USER in its final stage"
  elif [[ "$final_user" == "root" || "$final_user" == "0" || "$final_user" == "0:0" || "$final_user" == "root:root" ]]; then
    report "$dockerfile runs as root in its final stage (USER $final_user)"
  fi
done

ignore=".dockerignore"
if [[ ! -f "$ignore" ]]; then
  report "$ignore does not exist"
else
  for pattern in ".git" "**/node_modules" "web/dist" "**/build"; do
    if ! grep -qxF "$pattern" "$ignore"; then
      report "$ignore does not exclude $pattern"
    fi
  done
fi

# The jobs context reaches the push job as a GitHub artifact, which drops the executable bit. The launcher
# must be made executable in the image itself, so a COPY of bin needs a chmod of its entry point.
if [[ -f jobs/Dockerfile ]] && grep -qE '^[[:space:]]*COPY[[:space:]]+bin([[:space:]]|$)' jobs/Dockerfile; then
  if ! grep -qE '^[[:space:]]*RUN[[:space:]]+chmod[[:space:]]+0?[0-7]?[157][157][157][[:space:]]+/app/bin/jobs([[:space:]]|$)' jobs/Dockerfile; then
    report "jobs/Dockerfile copies bin without making /app/bin/jobs executable (RUN chmod 0755 /app/bin/jobs)"
  fi
fi

if [[ "$fail" -ne 0 ]]; then
  exit 1
fi
echo "PASS: container image checks"
